/* Video lessons: one narrated, animated lesson per lot. Narration is written to be spoken ("section" for s,
   "versus" for v). Visuals appear line by line. Quiz scenes use the lot's quick-fire statements (qi = index). */
(function (LL) {
  'use strict';

  LL.video(1, { title: 'Legal System, Land and Title', sub: 'Kampong Lorong Buangkok', scenes: [
    { t: 'title', say: ['Selamat datang to Lot 1. I\'m Pak Mat. In the next few minutes you\'ll learn how Singapore\'s legal system works, what counts as land, and what stays with the land when it is sold.', 'I\'ll stop you twice for a quick check, so stay awake.'] },
    { t: 'talk', head: 'The court ladder (L1)', points: ['Court of Appeal: the final court', 'High Court: General and Appellate Divisions', 'State Courts and Family Justice Courts', 'Privy Council appeals ended in 1994'],
      say: ['First, the system. Picture a ladder of courts.', 'At the top sits the Court of Appeal, Singapore\'s final court.', 'Below it, the High Court, with its General Division and Appellate Division.', 'Then the State Courts and the Family Justice Courts.', 'Appeals to the Privy Council in London ended in 1994. Check this ladder against your Lecture 1 slides.'] },
    { t: 'compare', head: 'What binds a judge?', left: 'Binding', right: 'Only persuasive', rows: [['The ratio decidendi of a higher Singapore court', 'Obiter dicta: remarks made in passing'], ['Decisions within the same court hierarchy', 'English and other foreign decisions']],
      say: ['Now, precedent.', 'A lower court must follow the ratio decidendi, the reason for the decision, of a higher court. Remarks made in passing, obiter dicta, only persuade.', 'English cases persuade too, but never bind. English common law and equity that applied before 12 November 1993 continue under the Application of English Law Act, so far as they suit Singapore.'] },
    { t: 'compare', head: 'Civil or criminal?', left: 'Civil', right: 'Criminal', rows: [['Claimant versus defendant', 'Public Prosecutor versus accused'], ['Balance of probabilities', 'Beyond reasonable doubt'], ['Damages or an injunction', 'A fine or prison']],
      say: ['Land disputes are civil, so know the difference.', 'A civil claim is brought by the injured party. A criminal case is brought by the Public Prosecutor.', 'Civil claims are proved on a balance of probabilities. Crimes must be proved beyond reasonable doubt.', 'The outcome is compensation or an injunction, not punishment. And remember: an arbitrator\'s award binds the parties, but a mediator only helps them settle.'] },
    { t: 'flow', head: 'Three layers of ownership', nodes: [
        { id: 's', label: 'The State', sub: 'owns all land', icon: 'scales', x: 14, y: 50, at: 0 },
        { id: 'e', label: 'An estate', sub: '99 or 999-year lease, or perpetuity', icon: 'house', x: 50, y: 50, at: 1 },
        { id: 't', label: 'Certificate of Title', sub: 'the proof', icon: 'scroll', x: 86, y: 50, at: 2 }],
      links: [{ from: 's', to: 'e', label: 'grants', at: 1 }, { from: 'e', to: 't', label: 'recorded on', at: 2 }],
      say: ['Now, land itself. Think in three layers.', 'The State owns all land and grants estates: an estate in perpetuity, or a lease of 99 or 999 years.', 'The Certificate of Title proves who holds the estate. And as a 99-year lease runs down, its value falls. That is lease decay.'] },
    { t: 'steps', head: 'Fixture or chattel? Two tests', steps: ['Degree of annexation: fixed, or resting on its own weight?', 'Object of annexation: improving the land, or enjoying the item?', 'Today, purpose carries more weight'],
      say: ['What goes with the land on a sale? Fixtures do, under section 6 of the CLPA. Chattels do not.', 'Test one, from Holland versus Hodgson: the degree of annexation. Fixed to the land suggests a fixture. Resting on its own weight suggests a chattel.', 'Test two: the object. Was it put there to improve the land permanently, or just so the item itself could be enjoyed?', 'Purpose now carries more weight. In D\'Eyncourt versus Gregory, statues resting on their own weight were fixtures, because they completed the design of the house.'] },
    { t: 'case', head: 'When the item is the building', name: 'Elitestone v Morris [1997]', facts: 'A bungalow rested on concrete pillars, with no foundations.', held: 'It was part and parcel of the land. A building is not a chattel.', cite: 'If the item IS the building, skip the two tests.',
      say: ['One case to remember.', 'In Elitestone versus Morris, a bungalow sat on concrete pillars with no foundations at all.', 'Held: it was part and parcel of the land. A building is not a chattel.', 'So if the item is the building itself, skip the two tests. The exception is local custom: a removable Malay stilt house was treated as a chattel in Kiah versus Sam.'] },
    { t: 'quiz', qi: 2 },
    { t: 'talk', head: 'Tenant\'s fixtures', points: ['Trade, ornamental and domestic fixtures', 'Remove them during the lease, or soon after', 'Make good any damage', 'Left behind after leaving? They are the landlord\'s'],
      say: ['Tenants get their own rule.', 'A tenant may remove trade, ornamental and domestic fixtures,', 'but only during the lease, or a short time after,', 'and must make good any damage.', 'Leave them behind after giving up possession, and they belong to the landlord.'] },
    { t: 'compare', head: 'How high? How deep?', left: 'Up', right: 'Down', rows: [['Only the airspace ordinary use needs (Bernstein v Skyviews)', 'If the title is silent: 30 m below the Singapore Height Datum (s 3B State Lands Act)'], ['A low sign or a swinging crane jib is trespass', 'Bocardo v Star Energy is the English rule, not ours']],
      say: ['Last question: how far up and down does land go?', 'Up: only the airspace you need for ordinary use. A plane taking photos from a reasonable height is no trespass, Bernstein versus Skyviews. Down: if your title is silent, 30 metres below the Singapore Height Datum.', 'But a low signboard, or a crane jib swinging over your roof, is trespass. And Bocardo, the English deep-drilling case, is not the Singapore rule.'] },
    { t: 'quiz', qi: 5 },
    { t: 'recap', points: ['Only the ratio of a higher court binds', 'State, then estate, then Certificate of Title', 'Fixtures: degree first, then purpose, and purpose wins', 'Tenants remove fixtures in time, or lose them', 'Airspace: ordinary use. Subsoil: 30 m'],
      say: ['Let\'s recap.', 'Only the ratio of a higher court binds.', 'Land runs from the State, to your estate, to the title.', 'Fixtures: degree first, then purpose, and purpose usually wins.', 'Tenants must remove their fixtures in time.', 'And ownership stops at ordinary airspace and 30 metres down. Now let\'s see what stuck. Your checkpoint quiz is next.'] }
  ] });

  LL.video(2, { title: 'Law and Equity', sub: 'Chancery Lane', scenes: [
    { t: 'title', say: ['Welcome to Chancery Lane. I\'m Madam Chan. This lesson explains why we have two bodies of rules, law and equity, and who is bound by an equitable right.'] },
    { t: 'flow', head: 'Where equity came from', nodes: [
        { id: 'c', label: 'A claimant', sub: 'wronged, no remedy', icon: 'house', x: 14, y: 50, at: 0 },
        { id: 'l', label: 'Common law courts', sub: 'no writ, no remedy', icon: 'gavel', x: 52, y: 22, at: 1 },
        { id: 'k', label: 'The Lord Chancellor', sub: 'decides by conscience', icon: 'scales', x: 52, y: 78, at: 2 }],
      links: [{ from: 'c', to: 'l', label: 'no writ fits', tone: 'bad', dash: true, at: 1 }, { from: 'c', to: 'k', label: 'petition', tone: 'ok', at: 2 }],
      say: ['Centuries ago in England, the common law was rigid.', 'If no writ fitted your claim, you had no remedy. And the usual remedy was only money.', 'So people petitioned the King, who passed the petitions to the Lord Chancellor. His Court of Chancery decided by conscience. That became equity, and it invented the trust.'] },
    { t: 'talk', head: 'Fusion in Singapore', points: ['One court applies law and equity (s 3 Civil Law Act)', 'Only administration was fused; the doctrines stay separate', 'In a conflict, equity prevails (Earl of Oxford\'s Case)'],
      say: ['Today in Singapore,', 'one court applies both, under section 3 of the Civil Law Act.', 'But only the administration was fused. The two sets of doctrines stay separate.', 'And where law and equity conflict, equity prevails. That goes back to the Earl of Oxford\'s Case in 1615.'] },
    { t: 'compare', head: 'Legal v equitable rights', left: 'Legal right', right: 'Equitable right', rows: [['Binds the whole world', 'Binds everyone except Equity\'s Darling'], ['For example, the registered owner', 'For example, a trust beneficiary, or a buyer under a signed contract']],
      say: ['Here is why this matters for land.', 'A legal right binds the whole world. An equitable right binds everyone except one person: Equity\'s Darling.', 'Who holds equitable rights? A trust beneficiary, or a buyer who has signed a contract but not yet completed.'] },
    { t: 'steps', head: 'Equity\'s Darling: four boxes', steps: ['Good faith', 'Value (a gift is not value)', 'Acquires the LEGAL estate', 'No notice: actual, constructive or imputed'],
      say: ['Equity\'s Darling must tick four boxes.', 'Good faith.', 'Value. A gift does not count.', 'The legal estate. This is the mark students drop most often. A buyer with only a contract is not protected.', 'And no notice. Not actual notice, not constructive notice, which is what proper inquiries would have shown, and not imputed notice, which is what your solicitor knew.'] },
    { t: 'trap', text: 'A buyer who has only a contract, not the legal estate, is not Equity\'s Darling.', say: ['Here\'s the trap. However honest the buyer is, without the legal estate they cannot be Equity\'s Darling.'] },
    { t: 'quiz', qi: 1 },
    { t: 'case', head: 'Equity looks at substance', name: 'Walsh v Lonsdale (1882)', facts: 'A written agreement for a 7-year lease, but no deed. The tenant moved in and paid rent.', held: 'Equity treated the agreement as the lease: equity treats as done what ought to be done.', cite: 'A specifically enforceable agreement for a lease is an equitable lease.',
      say: ['A famous case: Walsh versus Lonsdale.', 'There was a written agreement for a seven-year lease, but no deed. The tenant moved in and paid rent.', 'Equity treated the agreement as if it were the lease, because equity treats as done what ought to be done.', 'So a missing deed means no legal lease, but not no lease at all.'] },
    { t: 'compare', head: 'Remedies', left: 'Damages (common law)', right: 'Equitable remedies', rows: [['A right once breach is proved', 'Discretionary: specific performance, injunction, rescission'], ['Limited by remoteness (Hadley v Baxendale)', 'Refused for unclean hands or delay']],
      say: ['Every answer needs a remedy.', 'Damages are a right once breach is proved. Equitable remedies, like specific performance and injunctions, are discretionary.', 'Damages are limited by remoteness, Hadley versus Baxendale. Equity refuses claimants with unclean hands, or who sat on their rights too long.'] },
    { t: 'talk', head: 'The Torrens twist', points: ['On registered land, the register does the work of notice', 'Knowing of an unregistered interest is not fraud (s 47(2) LTA)', 'So protect an equitable interest with a caveat'],
      say: ['One more twist for registered land.', 'The register now does the work that notice used to do.', 'Knowing about someone\'s unregistered interest is not fraud, under section 47(2) of the Land Titles Act.', 'So anyone holding an equitable interest should lodge a caveat.'] },
    { t: 'quiz', qi: 10 },
    { t: 'recap', points: ['Equity: born in Chancery, acting on conscience', 'Fusion of administration, not doctrine', 'Equity\'s Darling: good faith, value, legal estate, no notice', 'Walsh v Lonsdale: agreement treated as a lease', 'On the register: caveat it'],
      say: ['Recap.', 'Equity was born in Chancery and acts on conscience.', 'Singapore fused the administration, not the doctrines.', 'Equity\'s Darling needs good faith, value, the legal estate, and no notice.', 'Walsh versus Lonsdale turns an agreement into an equitable lease.', 'And on registered land, protect it with a caveat. Checkpoint quiz coming up.'] }
  ] });

  LL.video(3, { title: 'Covenants', sub: 'Sunny Avenue, Nos. 11 & 13', scenes: [
    { t: 'title', say: ['Hello, I\'m Auntie Leong from Sunny Avenue. I sold No. 13 and kept No. 11. Today we find out whether the promises my buyer made can bind whoever owns No. 13 next.'] },
    { t: 'flow', head: 'The Sunny Avenue story', nodes: [
        { id: 'a', label: 'Mrs Leong', sub: 'No. 11: the benefit', icon: 'house', x: 14, y: 30, at: 0 },
        { id: 'g', label: 'Gabby', sub: 'No. 13: the burden', icon: 'house', x: 56, y: 30, at: 1 },
        { id: 's', label: 'The students', sub: 'tenants of No. 13', icon: 'tower', x: 56, y: 80, at: 2 },
        { id: 'n', label: 'A future buyer', sub: 'of No. 13', icon: 'sign', x: 88, y: 80, at: 3 }],
      links: [{ from: 'g', to: 'a', label: '3 covenants', at: 1 }, { from: 'g', to: 's', label: 'lets rooms', at: 2 }, { from: 'g', to: 'n', label: 'sells?', dash: true, at: 3 }],
      say: ['Here is the story from your past-year paper.', 'Mrs Leong sold No. 13 to Gabby, and Gabby gave three covenants: keep the roof in repair, private dwelling only, and maintain the boundary wall.', 'Then Gabby let rooms to nursing students.', 'The exam question is always the same: who is bound, and who can sue?'] },
    { t: 'compare', head: 'Positive or negative? Look at the cost', left: 'Positive: costs money', right: 'Negative: restrains use', rows: [['"Not to allow the roof to fall into disrepair"', '"Not to use other than as a private dwelling"'], ['"To maintain the boundary wall"', '"Not to build above two storeys"']],
      say: ['First, classify each covenant. Ignore the wording and ask what it costs to comply.', '"Not to allow the roof to fall into disrepair" sounds negative, but it costs money, so it is positive. "Private dwelling only" costs nothing. It is negative.', 'Maintaining a wall: positive. No building above two storeys: negative.'] },
    { t: 'trap', text: '"Not to allow ... to fall into disrepair" is POSITIVE. Classify by cost, not by wording.', say: ['That is the most common trap in this topic. Classify by cost, not by the words used.'] },
    { t: 'talk', head: 'Original parties: privity of contract', points: ['Mrs Leong and Gabby made the promise: contract decides', 'Gabby stays liable after letting or selling', 'No running rules needed between them'],
      say: ['Step two: are the original parties still in the picture?', 'Mrs Leong and Gabby made the promise, so privity of contract decides.', 'Gabby stays liable even after she moves out or sells.', 'You don\'t need the running rules between them at all.'] },
    { t: 'compare', head: 'Does it run to the next owner?', left: 'Common law', right: 'Equity', rows: [['Burden: NEVER (Austerberry; Rhone v Stephens)', 'Burden: negative covenants only, against a buyer with notice (Tulk v Moxhay)'], ['Benefit: if it touches and concerns the land (Swift)', 'Benefit: annexation, assignment or a building scheme']],
      say: ['Now the successors. Benefit and burden are separate questions.', 'The burden never runs at common law. Austerberry said so, and Rhone versus Stephens confirmed it. In equity, only a negative burden runs, against a buyer with notice. That is Tulk versus Moxhay.', 'The benefit passes more easily: at law if the covenant touches and concerns the land, and in equity by annexation, assignment or a building scheme.'] },
    { t: 'case', head: 'The equity route', name: 'Tulk v Moxhay (1848)', facts: 'A Leicester Square garden was sold with a promise to keep it open. Moxhay bought later, knew of the promise, and wanted to build.', held: 'Injunction. Buying with notice and ignoring the restriction is unconscionable.', cite: 'A negative covenant binds a successor with notice, in equity.',
      say: ['The case behind the equity route.', 'A garden in Leicester Square was sold with a promise to keep it open. Years later Moxhay bought it, knew about the promise, and wanted to build.', 'The court granted an injunction. Buying with notice and then ignoring the restriction is unconscionable.', 'On registered land, a covenant entered on the Certificate of Title gives the buyer that notice.'] },
    { t: 'quiz', qi: 2 },
    { t: 'steps', head: 'Getting round the positive burden rule', steps: ['Chain of indemnity covenants', 'Halsall v Brizell: take the benefit, bear the burden', 'Management corporation in a strata scheme', 'Sue the original covenantor'],
      say: ['Positive burdens don\'t run, so how do lawyers cope?', 'A chain of indemnity covenants passes the cost down the line.', 'Halsall versus Brizell: if you use the road, you pay for the road.', 'In strata developments, the management corporation collects contributions from every owner.', 'And you can always sue the original covenantor.'] },
    { t: 'quiz', qi: 0 },
    { t: 'recap', points: ['Classify by cost: positive or negative', 'Original parties: privity of contract', 'Burden: never at law; negative only in equity, with notice', 'Benefit: touch and concern, or annexation', 'Positive burdens: use a workaround'],
      say: ['Recap.', 'Classify every covenant by cost.', 'Between the original parties, privity of contract decides.', 'The burden never runs at law, and in equity only negative covenants run, against buyers with notice.', 'The benefit passes if it touches and concerns the land, or by annexation.', 'And positive burdens need a workaround. On to your checkpoint.'] }
  ] });

  LL.video(4, { title: 'Easements, Support and Licences', sub: 'Tai Seng Industrial Estate', scenes: [
    { t: 'title', say: ['I\'m Engineer Rahman, and this is the factory estate at Tai Seng. Today: rights over a neighbour\'s land, what happens when a neighbour digs, and why permission is not the same as a right.'] },
    { t: 'steps', head: 'Re Ellenborough Park: four tests', steps: ['A dominant and a servient tenement', 'It accommodates the dominant land', 'Different owners', 'Capable of grant: definite, and no ouster'],
      say: ['An easement is a right over a neighbour\'s land that passes with the land. It must pass four tests from Re Ellenborough Park.', 'One: a dominant tenement that benefits, and a servient tenement that carries the burden.', 'Two: the right must accommodate the dominant land, meaning it benefits the land itself, not just the owner.', 'Three: the two plots must have different owners.', 'Four: it must be capable of forming the subject of a grant. Definite, and not so big that it shuts the owner out.'] },
    { t: 'compare', head: 'Which test fails?', left: 'Claimed right', right: 'Why it fails', rows: [['Hill v Tupper: a boat-hire monopoly on a canal', 'Accommodation: a business perk, not a benefit to land'], ['Copeland v Greenhalf: storing vehicles; Batchelor v Marlow: all-day parking', 'Ouster: they exclude the servient owner']],
      say: ['The examiner loves borderline rights.', 'In Hill versus Tupper, a monopoly to hire boats on a canal failed test two. It was a business advantage, not a benefit to land.', 'Storing vehicles on a strip of land, and parking all day on weekdays, failed test four. They shut the owner out. That is ouster.'] },
    { t: 'quiz', qi: 3 },
    { t: 'flow', head: 'The basement dig (practice paper)', nodes: [
        { id: 'p', label: 'Printwell', sub: '4-storey printing factory', icon: 'factory', x: 20, y: 50, at: 0 },
        { id: 'c', label: 'Costco', sub: 'basement car park dig', icon: 'gavel', x: 80, y: 50, at: 1 }],
      links: [{ from: 'c', to: 'p', label: 'support removed: cracks!', tone: 'bad', at: 2 }],
      say: ['Here is the sample question from your practice paper.', 'Costco dug a basement car park right up to the boundary, with sheet piles but no continuous monitoring.', 'The soil settled, and Printwell\'s factory cracked so badly it had to stop operating.'] },
    { t: 'compare', head: 'The right of support', left: 'England', right: 'Singapore', rows: [['The natural right protects land only', 'Xpress Print v Monocrafts: the duty covers buildings too'], ['A building needs an easement of support (Dalton v Angus)', 'Add negligence for no monitoring; lost profits recoverable']],
      say: ['Every landowner has a natural right of support from the neighbouring soil.', 'In England, that protects the land only. A building needs an easement of support, as in Dalton versus Angus. In Singapore, Xpress Print versus Monocrafts extended the duty to buildings.', 'Then add negligence. Digging next to a factory with no monitoring is careless, and the lost profits follow the physical damage.'] },
    { t: 'trap', text: 'State BOTH lines: the English rule, then Xpress Print. Engineers\' advice does not excuse the digging owner.', say: ['Here\'s the trap. State both lines, then Xpress Print. And following your engineers\' advice does not excuse you. Costco can only claim a contribution from them.'] },
    { t: 'compare', head: 'Easement or licence?', left: 'Easement', right: 'Licence', rows: [['A property right in the land', 'Mere permission'], ['Binds later owners of the servient land', 'A bare licence is revocable and binds no buyer'], ['Created by grant, implication or long use', 'Estoppel if there was a promise, reliance and detriment (Inwards v Baker)']],
      say: ['Finally, a right versus permission.', 'An easement is a property right. A licence is just permission.', 'An easement binds later owners. A bare licence can be revoked and does not bind a buyer. A contractual licence binds a buyer only through a constructive trust, Ashburn Anstalt.', 'But if someone promised you could stay, and you relied on that to your cost, estoppel may protect you, as in Inwards versus Baker.'] },
    { t: 'quiz', qi: 9 },
    { t: 'recap', points: ['Four tests: one fact per test', 'Weak spots: accommodation and ouster', 'Support: England, then Xpress Print, then negligence', 'Easement binds buyers; a bare licence does not'],
      say: ['Recap.', 'Run all four tests, one fact per test.', 'Borderline rights fail on accommodation or ouster.', 'For support, give the English rule, then Xpress Print, then negligence.', 'And an easement binds buyers, while a bare licence does not. Checkpoint time.'] }
  ] });

  LL.video(5, { title: 'Mortgages', sub: 'Raffles Place', scenes: [
    { t: 'title', say: ['Raffles Place. I\'m Mr Ong, a retired credit officer. Every tower here lends against land. Let\'s learn what the borrower can always do, and what the bank may do when things go wrong.'] },
    { t: 'flow', head: 'Who\'s who', nodes: [
        { id: 'b', label: 'Mortgagor', sub: 'the borrower', icon: 'house', x: 18, y: 50, at: 0 },
        { id: 'l', label: 'Mortgagee', sub: 'the lender', icon: 'bank', x: 82, y: 50, at: 0 }],
      links: [{ from: 'l', to: 'b', label: 'loan', at: 1 }, { from: 'b', to: 'l', label: 'registered charge over the land', at: 1 }],
      say: ['First, don\'t mix up the names. The mortgagor is the borrower. The mortgagee is the lender.', 'The bank lends money, and takes a registered charge over the land. Under the Land Titles Act it holds a charge, not the legal title.', 'And the borrower always keeps the equity of redemption: the right to pay off the loan and take the land back free. Once a mortgage, always a mortgage.'] },
    { t: 'steps', head: 'Clogs: how to decide', steps: ['Profile the borrower: advised company, or vulnerable person?', 'Name the category: postponement, option, tie, penalty', 'Is redemption made illusory, or the deal oppressive?', 'Give the remedy: redeem free of the term'],
      say: ['Terms that shackle the right to redeem are called clogs. Here\'s the method.', 'Profile the borrower first. An advised company is held to its bargain. A vulnerable individual is protected.', 'Name the category of the term.', 'Ask whether it makes redemption illusory, or the bargain oppressive.', 'Then give the remedy: the borrower redeems free of the bad term.'] },
    { t: 'compare', head: 'Valid or void?', left: 'The term', right: 'The result', rows: [['Fairclough: redeem only 6 weeks before the lease ends', 'VOID: redemption made illusory'], ['Knightsbridge: 40 years; commercial, advised parties', 'VALID: held to their bargain'], ['Samuel v Jarrah: lender\'s option to buy the property', 'VOID: a classic clog'], ['Kreglinger: a separate deal to buy sheepskins', 'VALID: a collateral advantage']],
      say: ['Four cases you must know.', 'In Fairclough, the borrower could redeem only six weeks before his lease ran out. Void: redemption was worthless.', 'In Knightsbridge, companies agreed to repay over forty years. Valid: commercial, advised parties.', 'In Samuel versus Jarrah, the lender took an option to buy the mortgaged property. Void.', 'In Kreglinger, a separate deal to buy sheepskins survived repayment. Valid, as a collateral advantage.'] },
    { t: 'case', head: 'Penalty interest', name: 'Hong Leong Finance v Tan Gin Huay [1999]', facts: 'Two elderly, illiterate sisters. Contract rate 5.5 to 6.75%; default rate 18%.', held: 'The 18% default rate was a penalty. "Industry practice" was no answer.', cite: 'Default interest and vulnerable borrowers. Add BOM v BOK: infirmity exploited, burden shifts.',
      say: ['Now default interest.', 'In Hong Leong Finance, two elderly, illiterate sisters borrowed at about six percent, with eighteen percent on late payments.', 'Held: the eighteen percent was a penalty, out of all proportion to the lender\'s loss. Industry practice was no answer.', 'In your past-year paper the default rate was twenty-eight percent. Apply Hong Leong, and remember BOM versus BOK for unconscionability.'] },
    { t: 'quiz', qi: 5 },
    { t: 'steps', head: 'When the borrower defaults', steps: ['Possession: after one month\'s notice (s 75 LTA)', 'Power of sale: arisen AND exercisable (s 25 CLPA)', 'Sell with care for the true market value (Cuckmere)', 'No duty to wait for a better market'],
      say: ['When the borrower defaults, the bank has remedies.', 'Possession: only after default and one month\'s notice, under section 75 of the Land Titles Act.', 'Sale: the power must have arisen, meaning a deed, money due and no exclusion, and be exercisable, under one of the triggers in section 25 of the CLPA.', 'When it sells, it must take reasonable care to get the true market value. Selling cheaply to its own subsidiary breaches that duty.', 'But it need not wait for a better market. China and South Sea Bank.'] },
    { t: 'number', head: 'The lease link', big: '3 years', label: 'A mortgagor in possession may grant a lease of up to 3 years (s 23 CLPA); it binds the bank (s 89(1) LTA).',
      say: ['And the lease link. If the borrower lets the property after mortgaging it, section 23 of the CLPA allows an occupation lease of up to three years, which section 89 of the Land Titles Act treats as authorised. That is why Gabby\'s 24-month lease binds Bestbank.'] },
    { t: 'trap', text: 'Arisen needs ALL three conditions. Exercisable needs only ONE s 25 trigger.', say: ['The trap: the three conditions for the power to arise are all required, but any one trigger in section 25 makes it exercisable.'] },
    { t: 'quiz', qi: 6 },
    { t: 'recap', points: ['Mortgagor borrows; mortgagee lends', 'Profile the borrower, then name the clog', 'Penalty: out of all proportion (Hong Leong)', 'Possession needs notice; sale needs arisen + exercisable', 'Leases up to 3 years bind the bank'],
      say: ['Recap.', 'The mortgagor borrows and the mortgagee lends.', 'Profile the borrower, then name the clog.', 'A default rate out of all proportion is a penalty.', 'Possession needs a month\'s notice, and sale needs the power arisen and exercisable.', 'And leases of up to three years bind the bank. Your checkpoint is next.'] }
  ] });

  LL.video(6, { title: 'Leases and Licences', sub: 'Orchard Road', scenes: [
    { t: 'title', say: ['I\'m Madam Sim. I let shops on Orchard Road. Every tenant thinks the word "licence" on the agreement settles everything. Let me show you why it doesn\'t.'] },
    { t: 'steps', head: 'Street v Mountford', steps: ['Exclusive possession', 'For a term', 'At a rent'],
      say: ['If the occupier has three things, it is a lease, whatever the document is called.', 'Exclusive possession: they can keep everyone out, even the landlord.', 'For a term: a fixed or periodic period.', 'At a rent. As Lord Templeman said, a fork is a fork even if you call it a spade.'] },
    { t: 'compare', head: 'What defeats exclusive possession?', left: 'Fact', right: 'Effect', rows: [['Real services that need access: meals, daily room cleaning', 'Licence: a lodger (Abbeyfield; Marchant)'], ['A clause never meant to be used', 'A sham, so ignored (Antoniades v Villiers)'], ['A spare key "for emergencies"', 'Not enough on its own (Aslan v Murphy)']],
      say: ['So what can turn it into a licence?', 'Real attendance and services that need the owner to walk in at will. That makes the occupier a lodger.', 'But a clause the parties never meant to use, like a right to move someone else in, is a sham and gets ignored.', 'And a spare key kept for emergencies is not enough on its own. In your past-year paper, Gabby\'s locked room and weekly cleaner didn\'t stop the students having a lease.'] },
    { t: 'quiz', qi: 1 },
    { t: 'talk', head: 'Ending a lease', points: ['A fixed term ends when the term ends', 'A notice to quit only ends a periodic tenancy', 'Otherwise you need a break clause, or forfeiture'],
      say: ['Can the landlord just give notice?', 'A fixed-term lease ends when the term ends.', 'A notice to quit only ends a periodic tenancy.', 'Otherwise the landlord needs a break clause, or must forfeit. So Gabby\'s notice in month 18 of a 24-month lease does nothing.'] },
    { t: 'steps', head: 'Forfeiture in three steps', steps: ['A right to forfeit: a re-entry clause, or s 93 LTA for registered leases', 'The procedure: a s 18 CLPA notice, or s 18A for unpaid rent', 'No waiver: don\'t accept rent knowing of the breach'],
      say: ['To end a lease for breach, go through three steps.', 'First, a right to forfeit. Usually an express re-entry clause. Section 93 of the Land Titles Act implies one only in registered leases.', 'Second, the right procedure. For most breaches, a section 18 notice giving the tenant time to remedy. For unpaid rent, section 18A lets the tenant pay the arrears and costs and keep the lease.', 'Third, no waiver.'] },
    { t: 'trap', text: 'Accepting rent after you know of the breach waives the right to forfeit for that breach.', say: ['If the landlord accepts rent after finding out about the breach, it waives the right to forfeit for that breach.'] },
    { t: 'compare', head: 'After an assignment: who sues whom?', left: 'Privity of contract', right: 'Privity of estate', rows: [['Original landlord and original tenant', 'Current landlord and current tenant'], ['Lasts for the contractual term (City of London v Fell)', 'Covenants that touch and concern the land (Spencer\'s Case)']],
      say: ['When a lease is assigned, two kinds of privity matter. Always mention both.', 'Privity of contract links the original landlord and tenant. Privity of estate links the current ones.', 'The original tenant stays liable for the contractual term, City of London versus Fell. The assignee is bound by covenants that touch and concern the land, Spencer\'s Case.'] },
    { t: 'case', head: 'Quiet enjoyment', name: 'OUE v Three Sixty Degree [2013]', facts: 'A rooftop bar at Mandarin Orchard lost its licence over a fire-safety limit, withheld rent, and was re-entered.', held: 'The no-set-off clause worked. No breach of quiet enjoyment: the landlord does not underwrite profits.', cite: 'Caveat lessee; no-set-off clauses; the limits of quiet enjoyment.',
      say: ['A Singapore case on Orchard Road itself.', 'A rooftop bar lost its licence because of a fire-safety limit, stopped paying rent, and the landlord re-entered.', 'The court held the no-set-off clause worked, and there was no breach of quiet enjoyment. The landlord does not underwrite the tenant\'s profits.', 'The tenant takes the premises as it finds them: caveat lessee.'] },
    { t: 'quiz', qi: 12 },
    { t: 'recap', points: ['Exclusive possession, term, rent: a lease', 'Services, shams and keys: the usual traps', 'Fixed terms end at the end', 'Forfeiture: right, procedure, no waiver', 'Mention privity of contract AND estate'],
      say: ['Recap.', 'Exclusive possession for a term at a rent makes a lease.', 'Watch for services, shams and spare keys.', 'Fixed terms end at the end.', 'Forfeiture needs a right, the procedure, and no waiver.', 'And mention both kinds of privity. Checkpoint next.'] }
  ] });

  LL.video(7, { title: 'Co-ownership and Trusts', sub: 'Sentosa Cove', scenes: [
    { t: 'title', say: ['I\'m Ms Pillai, an estate lawyer. Two names on a title tell you very little. Today: how co-owners hold land, what happens when one dies, and who really owns the benefit.'] },
    { t: 'compare', head: 'Joint tenancy v tenancy in common', left: 'Joint tenancy', right: 'Tenancy in common', rows: [['Each owns the whole', 'Each owns a separate share'], ['Survivorship: the last one standing takes all', 'Shares pass by Will or intestacy'], ['The default for two names on the title (s 53(1) LTA)', 'Created by words like "in equal shares"']],
      say: ['First, how do they hold it at law?', 'Joint tenants each own the whole. Tenants in common own separate shares.', 'Joint tenancy carries survivorship: when one dies, the others take everything. A tenant in common\'s share passes by Will.', 'Two names on the title with no words of severance are joint tenants, under section 53(1) of the Land Titles Act.'] },
    { t: 'flow', head: 'Zen, Belle and the Will', nodes: [
        { id: 'z', label: 'Zen', sub: 'joint tenant, dies', icon: 'tower', x: 18, y: 40, at: 0 },
        { id: 'b', label: 'Belle', sub: 'joint tenant', icon: 'house', x: 82, y: 40, at: 0 },
        { id: 'k', label: 'The children', sub: 'Will: "all my assets"', icon: 'scroll', x: 50, y: 85, at: 1 }],
      links: [{ from: 'z', to: 'k', label: 'Will?', tone: 'bad', dash: true, at: 1 }, { from: 'z', to: 'b', label: 'survivorship', tone: 'ok', at: 2 }],
      say: ['Your past-year Case Study 2. Zen and Belle hold a penthouse as joint tenants.', 'Zen\'s Will left all his assets to his children.', 'But survivorship acts at the moment of death, before any Will. So the joint share goes to Belle, not to the children.'] },
    { t: 'trap', text: 'A Will cannot pass a joint tenant\'s share. Check whether anything severed it BEFORE death.', say: ['Remember: a Will cannot pass a joint share. Always check whether anything severed the joint tenancy before death.'] },
    { t: 'steps', head: 'Severing by statute', steps: ['A declaration in the approved form', 'Served on every other joint tenant', 'REGISTERED: severance takes effect only then'],
      say: ['Singapore has a three-step statutory route, in section 53 of the Land Titles Act.', 'Sign a declaration in the approved form.', 'Serve it on every other joint tenant.', 'And register it. Severance happens only on registration. Chan Lung Kien versus Chan Shwe Ching overruled Diaz versus Diaz on this.'] },
    { t: 'quiz', qi: 3 },
    { t: 'talk', head: 'Severing in equity (Williams v Hensman)', points: ['Acting on your own share: a sale or mortgage', 'Mutual agreement', 'A mutual course of dealing', 'NOT a Will, and NOT failed negotiations (Burgess v Rawnsley)'],
      say: ['Equity also recognises three routes.', 'Acting on your own share, for example selling or mortgaging it.', 'A mutual agreement between the co-owners.', 'Or a mutual course of dealing.', 'But a Will doesn\'t sever, and neither do failed buy-out talks, Burgess versus Rawnsley.'] },
    { t: 'steps', head: 'Who owns the benefit?', steps: ['Look for actual intention first (Goh Swee Fang)', 'No evidence? Presume a resulting trust for the payer', 'Advancement may rebut it: parent to child, husband to wife', 'Shares are fixed at acquisition (Lau Siew Kim)'],
      say: ['Now the trust behind the title.', 'Start with the evidence of actual intention. Presumptions are a last resort.', 'If there is no evidence, equity presumes a resulting trust for whoever paid. The person asserting the trust carries the burden of proof.', 'The presumption of advancement can rebut it between parent and child, or husband and wife. It does not traditionally help unmarried partners.', 'And the shares are fixed at the time of purchase. Later mortgage payments count only if that was the plan, Chan Yuen Lan.'] },
    { t: 'talk', head: 'Patricia Khoo: four scenarios', points: ['Benefit intended now: beneficial joint tenancy', 'Benefit only on death: resulting trust until then', 'No benefit intended: resulting trust', 'Unclear: fall back on the presumptions'],
      say: ['For names added without payment, use Patricia Khoo\'s four scenarios.', 'If the payer meant to benefit the other person right away, they are beneficial joint tenants.', 'If the benefit was only meant on the payer\'s death, there is a resulting trust until then.', 'If no benefit was meant at all, a resulting trust.', 'And if it\'s unclear, fall back on the presumptions. Zen\'s text, "to have and to hold forever", points to scenario one.'] },
    { t: 'quiz', qi: 7 },
    { t: 'recap', points: ['Legal title first, then the beneficial interest', 'Survivorship beats the Will', 'Statutory severance: declare, serve, REGISTER', 'Actual intention first; presumptions last', 'Women\'s Charter s 112 is for spouses only'],
      say: ['Recap.', 'Legal title first, then the beneficial interest.', 'Survivorship beats the Will.', 'Statutory severance needs declaration, service and registration.', 'Actual intention first, presumptions last.', 'And the Women\'s Charter division on divorce is for spouses only. Checkpoint time.'] }
  ] });

  LL.video(8, { title: 'Sale and Purchase: the Contract', sub: 'Punggol', scenes: [
    { t: 'title', say: ['Hi, I\'m Marcus. I lost my dream flat in Punggol over a WhatsApp chat. Learn from my mistake: when does a land deal become a binding contract?'] },
    { t: 'steps', head: 'Three steps for every sale question', steps: ['Is there a valid contract?', 'Is it enforceable: signed writing, or part performance?', 'What remedy? And if no contract, what then?'],
      say: ['Every sale question runs in three steps.', 'One: is there a valid contract? Offer, acceptance, and an intention to be bound.', 'Two: is it enforceable? Land contracts need signed writing, or part performance.', 'Three: what remedy follows? And if there\'s no contract, what happens to the money and any caveat?'] },
    { t: 'flow', head: 'My WhatsApp deal', nodes: [
        { id: 'm', label: 'Marcus', sub: 'buyer', icon: 'pen', x: 16, y: 32, at: 0 },
        { id: 'l', label: 'Mr Lee', sub: 'seller', icon: 'house', x: 62, y: 32, at: 0 },
        { id: 'r', label: 'Rival buyer', sub: 'offers $1.25m', icon: 'sign', x: 62, y: 85, at: 2 }],
      links: [{ from: 'm', to: 'l', label: '$1.18m + $1,000 "goodwill"', at: 1 }, { from: 'l', to: 'm', label: '"subject to contract"', dash: true, at: 1 }, { from: 'l', to: 'r', label: 'grants an OTP', tone: 'bad', at: 2 }],
      say: ['Here\'s what happened.', 'We agreed a price on WhatsApp and I paid a thousand dollars as a "goodwill deposit". But every message from Mr Lee ended "subject to contract".', 'Then someone offered more, and he granted them an option to purchase.'] },
    { t: 'compare', head: '"Subject to contract": cite both cases', left: 'Norwest v Newport Mining (2011)', right: 'OCBC v Wong Hua Choon (2012)', rows: [['A strong presumption: no contract yet', 'The label is not decisive'], ['Only strong context rebuts it', 'Look at all the circumstances, objectively']],
      say: ['Two Court of Appeal cases sit on either side. Always cite both.', 'Norwest says the label creates a strong presumption that there is no contract yet. OCBC says the label is not decisive.', 'Only strong context rebuts the presumption, so look at all the circumstances, objectively. In my case, the repeated label and the promised OTP meant no contract.'] },
    { t: 'quiz', qi: 4 },
    { t: 'talk', head: 'Options to purchase', points: ['To the buyer: an irrevocable offer (Spiro v Glencrown)', 'The contract forms when the option is exercised', 'Exercise exactly as the OTP says (JT Chanrai)', 'Option fee about 1%, deposit about 10%, stamp duty within 14 days'],
      say: ['Most Singapore sales use an option to purchase.', 'To the buyer, it is an irrevocable offer. The seller cannot withdraw during the option period.', 'The contract only forms when the buyer exercises the option.', 'And exercise must follow the OTP exactly, in time and in the right form, JT Chanrai.', 'Typical numbers: an option fee of about one percent, a deposit of about ten percent, and stamp duty within fourteen days of exercise.'] },
    { t: 'talk', head: 'Writing: s 6(d) Civil Law Act', points: ['Signed by the party being sued', 'The 3 Ps: parties, property, price', 'Emails can count (Joseph Mathew)', 'Or part performance, unequivocally referable (Hu Lee Impex)'],
      say: ['Enforceability. Under section 6(d) of the Civil Law Act, you can\'t sue on a land contract without signed writing.', 'It must be signed by the party you are suing,', 'and show the three Ps: parties, property and price.', 'Emails have been accepted as writing.', 'Without writing, you need part performance: acts that point clearly to this contract, like moving in and renovating.'] },
    { t: 'trap', text: 'A small "goodwill" payment is equivocal: not part performance, and not an option fee.', say: ['My thousand-dollar goodwill payment proved nothing. A small payment is equivocal. It is not part performance, and it is not an option fee.'] },
    { t: 'compare', head: 'Misrepresentation', left: 'Actionable', right: 'Not actionable', rows: [['A false statement of fact: "no seepage"', 'A pure opinion or a sales puff'], ['A half-truth from someone who knows better', 'Silence, as a general rule']],
      say: ['One more thing: what the seller or agent tells you.', 'A false statement of fact, like "no seepage", is actionable. A pure opinion or sales talk is not.', 'A half-truth from someone who knows the truth is actionable too. Fraudulent misrepresentation follows Derry versus Peek, and negligent misrepresentation falls under section 2(1) of the Misrepresentation Act.'] },
    { t: 'quiz', qi: 9 },
    { t: 'recap', points: ['Contract, then enforceability, then remedy', 'Subject to contract: Norwest and OCBC', 'OTP: exercise exactly, in time', 'Signed writing or part performance', 'No contract: no caveat, get the money back'],
      say: ['Recap.', 'Contract, then enforceability, then remedy.', 'For subject to contract, cite Norwest and OCBC.', 'Exercise an option exactly as it says.', 'Land contracts need signed writing or part performance.', 'And if there\'s no contract, don\'t caveat. Just get your money back. On to the checkpoint.'] }
  ] });

  LL.video(9, { title: 'Torrens Title, Caveats and Stamp Duty', sub: 'Newton · the Land Registry', scenes: [
    { t: 'title', say: ['I\'m Mr Lim from the Land Registry. In Singapore, the register is king. Let\'s see who wins when a forger gets involved, and how a caveat protects you.'] },
    { t: 'talk', head: 'The register is king', points: ['Registration is the source of title (s 45)', 'Once registered, title is indefeasible (s 46(1))', 'Immediate indefeasibility (Frazer v Walker)'],
      say: ['Three rules first.', 'Registration is what passes title, under section 45 of the Land Titles Act.', 'Once registered, the title is indefeasible, under section 46(1).', 'And Singapore follows immediate indefeasibility, from Frazer versus Walker. An innocent buyer who registers takes good title, even under a forged document.'] },
    { t: 'flow', head: 'The forged transfer', nodes: [
        { id: 'o', label: 'Mr Ong', sub: 'true owner', icon: 'house', x: 14, y: 30, at: 0 },
        { id: 's', label: 'Seng', sub: 'the forger', icon: 'pen', x: 14, y: 82, at: 1 },
        { id: 'b', label: 'Bobby', sub: 'registered buyer', icon: 'stamp', x: 56, y: 56, at: 1 },
        { id: 'h', label: 'Harbour Bank', sub: 'registered mortgagee', icon: 'bank', x: 88, y: 56, at: 2 }],
      links: [{ from: 's', to: 'b', label: 'forged transfer', tone: 'bad', at: 1 }, { from: 'b', to: 'h', label: 'mortgage', at: 2 }],
      say: ['The case study from your Q and A bank.', 'Seng forged his uncle\'s signature and transferred the house to Bobby, whose own lawyer had warned him the signature looked wrong. Bobby said, "just register it".', 'Then Bobby mortgaged the house to Harbour Bank, which checked the register and suspected nothing.'] },
    { t: 'compare', head: 'Fraud, or not fraud?', left: 'Fraud (s 46(2)(a))', right: 'Not fraud', rows: [['Actual dishonesty by the proprietor or his agent', 'Carelessness (Assets Co; UOB v Bebe)'], ['Wilful blindness after suspicion (Waimiha)', 'Mere knowledge of an unregistered interest (s 47(2))'], ['A promise never meant to be kept (Loke Yew)', 'A stranger\'s forgery the buyer knew nothing of']],
      say: ['The main exception is fraud, in section 46(2)(a). But whose fraud, and what counts?', 'It must be actual dishonesty by the registered proprietor or his agent. Carelessness is not enough, as the Court of Appeal said in UOB versus Bebe.', 'Deliberately shutting your eyes after suspicion is aroused counts. That is wilful blindness, and it is Bobby. Merely knowing about someone\'s unregistered interest does not count.', 'A promise never meant to be kept is fraud. But a stranger\'s forgery does not defeat an innocent buyer.'] },
    { t: 'quiz', qi: 2 },
    { t: 'talk', head: 'Who else is protected?', points: ['Only purchasers: good faith and value (s 4)', 'A donee takes no better title (s 46(3))', 'Judge each registered person separately'],
      say: ['Three more rules.', 'Only purchasers, who act in good faith and give value, are protected.', 'Someone who receives the land as a gift takes no better title than the giver.', 'And judge each registered person separately. Bobby\'s title falls, but the innocent bank\'s mortgage stands. Mr Ong gets his house back, still subject to the bank\'s mortgage.'] },
    { t: 'steps', head: 'Caveats', steps: ['Lodge it for an existing interest in land (s 115)', 'A bare right to money is not enough (Salbiah)', 'Removal: open with s 127(1) or s 127(2), and say why', 'Lapses after 5 years; 30 days once a dealing is lodged'],
      say: ['Unregistered interests need a caveat.', 'You can lodge one only for an interest in land that exists now, under section 115.', 'A bare right to be paid money is not enough.', 'To remove one, always open by choosing section 127(1) or 127(2), and say why. Where the facts are disputed, the court asks if there is a serious question to be tried.', 'A caveat lapses after five years, or in thirty days once a dealing is lodged and no court order is obtained.'] },
    { t: 'number', head: 'ABSD', big: '60%', label: 'ABSD for foreigners. Joint buyers with different profiles pay the HIGHER rate on the whole price (slide figures).',
      say: ['Stamp duty. Buyers also pay ABSD, additional buyer\'s stamp duty. On your lecture figures, a foreigner pays sixty percent. When joint buyers have different profiles, the higher rate applies to the whole price. It is never averaged. That is practice-paper question four: Claire and Andre pay the higher rate.'] },
    { t: 'quiz', qi: 10 },
    { t: 'recap', points: ['Registration gives title; immediate indefeasibility', 'Fraud: the proprietor\'s own dishonesty', 'Wilful blindness counts; carelessness does not', 'Each registered person judged separately', 'Caveat: open with s 127(1) or (2)'],
      say: ['Recap.', 'Registration gives title, and Singapore follows immediate indefeasibility.', 'Fraud means the proprietor\'s own dishonesty.', 'Wilful blindness counts. Carelessness does not.', 'Judge each registered person separately.', 'And for caveats, open with section 127(1) or 127(2). Checkpoint next.'] }
  ] });

  LL.video(10, { title: 'Agency and Estate Agency', sub: 'Toa Payoh', scenes: [
    { t: 'title', say: ['I\'m Ms Teo, a compliance officer. Estate agents handle the biggest purchase most people ever make. So the law asks a lot of them. Let\'s see how much.'] },
    { t: 'steps', head: 'An agent is a fiduciary', steps: ['Good faith and loyalty', 'No conflict of interest', 'No secret profit', 'Disclose everything material, including every offer'],
      say: ['An agent is a fiduciary. That means four duties.', 'Act in good faith and with loyalty.', 'Avoid conflicts of interest. Selling to a relative without telling the seller is a conflict, McPherson versus Watt.', 'Make no secret profit.', 'And disclose everything material, including every single offer.'] },
    { t: 'compare', head: 'Honest or dishonest?', left: 'Hippisley v Knee Bros (honest)', right: 'Andrews v Ramsay (dishonest)', rows: [['Kept trade discounts, without realising it was wrong', 'Took a secret commission from the other side'], ['Must account for the profit', 'Must account AND forfeits commission'], ['Keeps the agreed commission', 'A bribe is held on constructive trust (FHR v Cedar)']],
      say: ['Secret profits come in two flavours.', 'In Hippisley versus Knee Brothers, an honest auctioneer kept trade discounts. In Andrews versus Ramsay, a dishonest agent took money from the other side.', 'Both must account for the profit, but the dishonest agent also loses his commission.', 'The honest one keeps his commission. And a bribe is held on constructive trust for the principal, FHR versus Cedar Capital. That is your practice-paper KFM question: KFM repays the discounts, but keeps its two percent.'] },
    { t: 'trap', text: 'A trade custom the principal didn\'t know about is no defence to a secret profit.', say: ['The trap: "it\'s the custom of the trade" is no defence if the principal did not know about it.'] },
    { t: 'quiz', qi: 1 },
    { t: 'flow', head: 'Kelvin and his cousin', nodes: [
        { id: 'l', label: 'The Lees', sub: 'sellers', icon: 'house', x: 14, y: 30, at: 0 },
        { id: 'k', label: 'Kelvin', sub: 'their agent', icon: 'sign', x: 50, y: 30, at: 0 },
        { id: 'x', label: 'Two buyers', sub: '$1.32m offers', icon: 'pen', x: 86, y: 30, at: 1 },
        { id: 'o', label: 'Orchid Holdings', sub: 'Kelvin\'s cousin', icon: 'bank', x: 50, y: 85, at: 2 }],
      links: [{ from: 'l', to: 'k', label: 'appoint, 1%', at: 0 }, { from: 'x', to: 'k', label: 'offers hidden', tone: 'bad', dash: true, at: 1 }, { from: 'o', to: 'k', label: '$4,000 "fee"', tone: 'bad', at: 2 }],
      say: ['A case study from your Q and A bank. The Lees appointed Kelvin to sell their condo.', 'Two buyers offered 1.32 million dollars. Kelvin never passed those offers on.', 'Instead he steered the sale to his cousin\'s company at 1.18 million, and took a four-thousand-dollar "appreciation fee" from it. That\'s a conflict, suppressed offers, and a bribe.'] },
    { t: 'steps', head: 'Remedies for a bribe', steps: ['Account for the secret profit', 'Constructive trust over the bribe (FHR)', 'Rescind the tainted contract', 'Forfeit commission and claim damages'],
      say: ['List the remedies one by one, then pick the ones that fit.', 'The agent accounts for the profit.', 'The bribe is held on constructive trust.', 'The Lees can rescind the sale to Orchid before completion.', 'Kelvin forfeits his commission, and the Lees can claim damages for the lost hundred and forty thousand.'] },
    { t: 'compare', head: 'Who earns commission?', left: 'Exclusive (CEA form)', right: 'Non-exclusive', rows: [['Any binding sale in the validity period (Clause 6)', 'Only the effective cause of the sale (Grandhome)'], ['Even if the agent never met the buyer', 'Look for a break in the chain: time, price, another agent']],
      say: ['Finally, commission.', 'Under the exclusive CEA form, Clause 6 makes commission due on any binding sale during the validity period. Under a non-exclusive arrangement, only the agent who was the effective cause of the sale gets paid, Grandhome.', 'That is true even if the exclusive agent never met the buyer. For non-exclusive agents, look for a break in the chain: time passing, a price change, or another agent doing the persuading.'] },
    { t: 'quiz', qi: 6 },
    { t: 'recap', points: ['Fiduciary: loyalty, no conflict, no secret profit, disclose', 'Honest agent accounts; dishonest agent also forfeits', 'Bribes: account, trust, rescind, forfeit, damages', 'Exclusive: Clause 6. Non-exclusive: effective cause', 'Apparent authority comes from the principal'],
      say: ['Recap.', 'Agents are fiduciaries.', 'An honest agent accounts for a secret profit. A dishonest one also forfeits his commission.', 'For bribes, list the remedies.', 'Exclusive agency pays on any sale in the period. Non-exclusive pays the effective cause.', 'And apparent authority must come from the principal, never from the agent alone. That\'s all ten lots. After this checkpoint, the Exam Hall is waiting.'] }
  ] });
})(window.LL);
